import{_ as o,o as e,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Ações favoritas do processo","description":"","frontmatter":{"title":"Ações favoritas do processo","id":"eproc-acoes-favoritas","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.0.5","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-acoes-favoritas"}]]},"headers":[],"relativePath":"funcionalidades/eproc-acoes-favoritas.md","filePath":"funcionalidades/eproc-acoes-favoritas.md"}'),t={name:"funcionalidades/eproc-acoes-favoritas.md"};function i(d,a,c,n,l,u){return e(),s("div",null,a[0]||(a[0]=[r('<h1 id="acoes-favoritas-do-processo" tabindex="-1">Ações favoritas do processo <a class="header-anchor" href="#acoes-favoritas-do-processo" aria-label="Permalink to &quot;Ações favoritas do processo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O painel de ações do eproc (Árvore, Minutar, Intimar e muitos outros botões) costuma ser longo. Este recurso permite marcar as ações que você mais usa como favoritas, para que fiquem em destaque no início do painel, e esconder numa pasta as que você nunca usa. Os botões também podem ganhar ícones.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, painel de ações da página do processo e de outras telas que tenham painel de ações.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Passe o mouse sobre um botão de ação. Aparecem dois pequenos selos: um à esquerda, para favoritar, e um à direita (olho riscado), para ocultar.</li><li>Para favoritar, passe o mouse sobre o selo da esquerda e clique (&quot;Marcar como ação favorita&quot;). O botão ganha a cor de favorito e, com o agrupamento ligado, vai para o início do painel.</li><li>Para tirar dos favoritos, clique de novo no selo (&quot;Remover das favoritas&quot;).</li><li>Para ocultar uma ação, clique no selo da direita (&quot;Ocultar esta ação&quot;). Ela vai para a pasta <strong>Ocultas</strong>, no fim do painel, que mostra quantas ações estão ali.</li><li>Para recuperar uma ação oculta, abra a pasta (&quot;Mostrar as ações ocultas&quot;) e use &quot;Desocultar esta ação&quot;, ou favorite-a direto dali (favoritar também desoculta). A pasta fecha ao clicar fora dela.</li></ol><p>Favoritas e ocultas valem para todos os processos.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Agrupar as ações favoritas</td><td>ligada</td><td>Reúne as favoritas no início do painel. Desligada, elas só mudam de cor e ficam no lugar original.</td></tr><tr><td>Ícones nos botões de ação</td><td>Em todos os botões de ação</td><td>Também pode ser &quot;Nas ações favoritadas&quot; ou &quot;Nenhum ícone&quot;.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A ação é reconhecida pelo endereço do botão. Se o eproc mudar o endereço de uma ação, ela deixa de ser reconhecida como favorita ou oculta e precisa ser marcada de novo.</li><li>O ícone de cada botão é escolhido automaticamente pelo nome da ação. Ações sem correspondência ficam com um ícone genérico.</li></ul>',12)]))}const f=o(t,[["render",i]]);export{m as __pageData,f as default};
